/**
 * Writes the renderer's A2UI 1.0 capabilities, as generated by web_core
 * itself, to streamlit_a2ui/renderer_capabilities.json for
 * renderer_capabilities() to return.
 *
 * The file sits in the Python package, outside the publicly served asset_dir.
 * The processor is built exactly as src/session.ts builds it: the basic
 * catalog only, protocol 1.0, no inline catalogs.
 */
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { MessageProcessor } from "@a2ui/web_core";
import { basicCatalog } from "@a2ui/web_core/catalogs/basic/v1";

const target = fileURLToPath(
  new URL("../../renderer_capabilities.json", import.meta.url),
);

const processor = new MessageProcessor([basicCatalog], undefined, {
  version: "1.0",
});
const capabilities = processor.getRendererCapabilities({ versions: ["1.0"] });
processor.dispose();

writeFileSync(target, `${JSON.stringify(capabilities, null, 2)}\n`);
console.log(`wrote ${target}`);
